1	package com.example.starter.service;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDateTime;
5	import java.util.List;
6	import java.util.Map;
7	import java.util.stream.Collectors;
8	
9	import org.springframework.jdbc.core.JdbcTemplate;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.annotation.Transactional;
12	
13	import com.example.starter.web.ConflictException;
14	import com.example.starter.web.dto.MergeRequest;
15	import com.example.starter.web.dto.MergeResponse;
16	import com.example.starter.web.dto.RestoreChainView;
17	import com.example.starter.web.dto.SealResponse;
18	import com.example.starter.web.dto.WorkOrderView;
19	
20	/**
21	 * 工单服务：工单合并（原单引用新单并保留轨迹）、日结封存（终态）、详情与复电确认链复算。
22	 */
23	@Service
24	public class WorkOrderService {
25	
26	    private static final Map<String, Integer> LEVEL_RANK = Map.of(
27	            "NONE", 0, "SECOND", 1, "FIRST", 2, "SPECIAL", 3);
28	
29	    private final JdbcTemplate jdbc;
30	    private final WorkOrderStore store;
31	    private final EscalationService escalation;
32	
33	    public WorkOrderService(JdbcTemplate jdbc, WorkOrderStore store, EscalationService escalation) {
34	        this.jdbc = jdbc;
35	        this.store = store;
36	        this.escalation = escalation;
37	    }
38	
39	    /**
40	     * 合并工单：源单须为同馈线的待派单/挂单；合并生成新单，源单置为 MERGED 并引用新单。
41	     */
42	    @Transactional
43	    public MergeResponse merge(MergeRequest req) {
44	        List<Long> ids = req.sourceOrderIds().stream().distinct().toList();
45	        if (ids.size() < 2) {
46	            throw new IllegalArgumentException("合并至少需要两张源工单");
47	        }
48	        List<WorkOrderRow> sources = ids.stream().map(store::requireById).toList();
49	        for (WorkOrderRow source : sources) {
50	            if (!"PENDING".equals(source.status()) && !"QUEUED".equals(source.status())) {
51	                throw new ConflictException("工单状态不可合并: id=" + source.id() + " status=" + source.status());
52	            }
53	        }
54	        String feeder = sources.get(0).feederId();
55	        if (sources.stream().anyMatch(o -> !feeder.equals(o.feederId()))) {
56	            throw new ConflictException("仅同馈线工单可合并");
57	        }
58	        String faultPoint = sources.stream().map(WorkOrderRow::faultPoint)
59	                .collect(Collectors.joining("+"));
60	        int affected = sources.stream().mapToInt(WorkOrderRow::affectedUsers).sum();
61	        String level = sources.stream().map(WorkOrderRow::importantLevel)
62	                .max((a, b) -> Integer.compare(LEVEL_RANK.get(a), LEVEL_RANK.get(b))).orElse("NONE");
63	        LocalDateTime outageStart = sources.stream().map(WorkOrderRow::outageStartAt)
64	                .min(LocalDateTime::compareTo).orElseThrow();
65	
66	        long newId = store.insertOrder(feeder, faultPoint, affected, level, "PENDING", outageStart);
67	        store.addEvent(newId, "CREATED_BY_MERGE", "由工单" + ids + "合并生成");
68	        for (WorkOrderRow source : sources) {
69	            jdbc.update("UPDATE work_order SET status = 'MERGED', merged_into_id = ? WHERE id = ?",
70	                    newId, source.id());
71	            store.addEvent(source.id(), "MERGED", "合并至工单" + newId);
72	        }
73	        return new MergeResponse(newId, ids);
74	    }
75	
76	    /**
77	     * 日结封存：仅已复电工单可封存；封存为终态，重复封存返回幂等成功。
78	     */
79	    @Transactional
80	    public SealResponse seal(long workOrderId) {
81	        WorkOrderRow order = store.requireById(workOrderId);
82	        if ("SEALED".equals(order.status())) {
83	            return new SealResponse(workOrderId, "SEALED", true);
84	        }
85	        if (!"RESTORED".equals(order.status())) {
86	            throw new ConflictException("仅已复电工单可日结封存: " + order.status());
87	        }
88	        jdbc.update("UPDATE work_order SET status = 'SEALED' WHERE id = ?", workOrderId);
89	        store.addEvent(workOrderId, "SEALED", "日结封存");
