    /** 批量评估特级工单发电车升级，返回本次新触发的工单ID。 */
    @PostMapping("/escalations/check")
    public Map<String, List<Long>> checkEscalations() {
        return Map.of("triggered", escalation.evaluateAll());
    }
}

